  }

  // Check performance / network requests in performance entries
  const perf = performance.getEntriesByType('resource')
    .map(r => r.name)
    .filter(name => name.includes('bazaarvoice') || name.includes('reviews'));
  results.bvUrls = perf;

  return results;
});

