const digitalIds = [
  "0704385", // Sony PlayStation 5 Digital Edition - Slim; 825 GB
  "0675012", // Sony PlayStation 5 Digital Edition - Slim; 1 TB
  "0704490", // Fortnite bundle
  "0696518", // Black Ops 6 bundle
  "0688391", // Cobalt Star bundle
  "0686679", // NBA 2K25 bundle
  "0679303"  // Spider-Man 2 bundle
];

const reviewsByProduct = await browserjs(tabId, async (ids) => {
  const results = {};
  for (const id of ids) {
    const url = `https://apps.bazaarvoice.com/api/data/reviews.json?apiversion=5.4&passkey=61lw6av5qh6kpo8qgkmtyboxi&filter=ProductId:${id}&sort=Helpfulness:desc`;
    const r = await fetch(url);
    const j = await r.json();
    results[id] = {
      total: j.TotalResults,
      reviews: (j.Results || []).map(x => ({
        id: x.Id,
        author: x.UserNickname,
        rating: x.Rating,
        title: x.Title,
        text: x.ReviewText,
        submissionTime: x.SubmissionTime,
        helpfulness: x.Helpfulness,
        totalPositiveFeedbackCount: x.TotalPositiveFeedbackCount,
        totalNegativeFeedbackCount: x.TotalNegativeFeedbackCount,
        isRatingsOnly: x.IsRatingsOnly
      }))
    };
  }
  return results;
}, digitalIds);

